INSERT INTO risk_knowledge_entries (id,slug,knowledge_version,status,category,title,problem_json,evidence_chain_json,review_json,claims_boundary,content_digest,created_at,updated_at) VALUES ('ARL-KB-001','agent-purpose-is-undefined-or-expands-without-approval','ARL-RKA-1.0.0','active','Governance and scope','Agent purpose is undefined or expands without approval','{"statement": "The agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do.", "customer_symptom": "Customers may see unexplained behaviour, missing evidence or a deployment blocker related to: agent purpose is undefined or expands without approval.", "credible_failure_or_attack": "The agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do.", "affected_assets": ["agent", "model context", "tools or downstream systems", "customer evidence"], "default_severity": "high", "severity_rationale": "Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.", "applicability": ["all agents"]}','["Declared Controls", "Observed Controls", "Findings", "Red-Team Evidence", "Runtime Evidence", "Human Approval", "Remediation", "Retest", "Deployment Decision"]','{"human_review_required": true, "last_reviewed": "2026-08-05", "next_review_due": "2026-11-05", "change_triggers": ["material source update", "new attack evidence", "customer incident", "control bypass", "product architecture change"], "review_status": "initial expert-authored candidate; customer and independent practitioner validation required"}','This entry supports a proprietary AgentRiskLayer assessment. It is not an accredited certification, legal opinion or guarantee that the system is risk-free.','77b6fa1b3702e364454f38f84119737ea2613065afbe05e5db7db4877ed4f391','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,knowledge_version=excluded.knowledge_version,status=excluded.status,category=excluded.category,title=excluded.title,problem_json=excluded.problem_json,evidence_chain_json=excluded.evidence_chain_json,review_json=excluded.review_json,claims_boundary=excluded.claims_boundary,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
INSERT INTO risk_knowledge_checks (id,entry_id,objective,method,check_types_json,required_evidence_json,pass_condition,fail_condition,limitations,content_digest,created_at,updated_at) VALUES ('ARL-CHK-001','ARL-KB-001','Determine whether the assessed system prevents or detects: agent purpose is undefined or expands without approval.','Compare the declared purpose, production prompts, tool catalogue and recent change history; flag capabilities that are not necessary for an approved use case.','["declared-control review", "observed-control inspection", "negative or abuse test", "evidence review"]','["Assessed system, version, environment and scope", "Relevant code, configuration, policy or architecture evidence", "Executed test input and observed result", "Identity, timestamp and evidence digest where appropriate"]','The control is observed in the assessed version, the negative test is denied or safely contained, and the evidence is attributable and reproducible.','The control is absent, self-declared only, bypassable, fail-open, cross-tenant, replayable, unauditable or outside the assessed scope.','A passing bounded check does not prove the absence of other paths, future regressions or risks outside the stated scope.','2909bdafbddcb28afd810c58573b7f80f7c25eabd357ec35338f79a4b3ed01e3','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,objective=excluded.objective,method=excluded.method,check_types_json=excluded.check_types_json,required_evidence_json=excluded.required_evidence_json,pass_condition=excluded.pass_condition,fail_condition=excluded.fail_condition,limitations=excluded.limitations,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
INSERT INTO risk_knowledge_solutions (id,entry_id,control_objective,recommended_remediation,default_owner,priority,implementation_principles_json,monitoring,containment,retest_acceptance_json,content_digest,created_at,updated_at) VALUES ('ARL-SOL-001','ARL-KB-001','Reduce the likelihood and impact of agent purpose is undefined or expands without approval and make the remaining risk visible.','Record a versioned purpose, permitted outcomes, prohibited outcomes and accountable owner; require change approval before adding authority or data access.','Product owner','P1','["Apply enforcement outside the model where authority, identity, money, data or side effects are involved.", "Use least privilege and fail closed for material actions.", "Preserve versioned evidence and rollback."]','Monitor denials, bypass attempts, drift, exceptions, anomalous use and control failures with a named response owner.','Disable or scope the affected capability, revoke related authority and preserve evidence until remediation is verified.','["Repeat the original failure case against the exact remediated version.", "Run authorization, tenant, replay, race and malformed-input variants where applicable.", "Confirm expected denial or bounded safe behaviour and no unintended side effects.", "Record evidence digest, limitations, reviewer and retest status."]','20dcffad1856e390318eb4cbc729ee0b45d280d87ceb83dca842894650553d3c','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,control_objective=excluded.control_objective,recommended_remediation=excluded.recommended_remediation,default_owner=excluded.default_owner,priority=excluded.priority,implementation_principles_json=excluded.implementation_principles_json,monitoring=excluded.monitoring,containment=excluded.containment,retest_acceptance_json=excluded.retest_acceptance_json,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
