INSERT INTO risk_knowledge_checks (id,entry_id,objective,method,check_types_json,required_evidence_json,pass_condition,fail_condition,limitations,content_digest,created_at,updated_at) VALUES ('ARL-CHK-003','ARL-KB-003','Determine whether the assessed system prevents or detects: prohibited uses and harm boundaries are missing.','Review policy, prompts and tool rules for explicit prohibited uses and test representative forbidden requests.','["declared-control review", "observed-control inspection", "negative or abuse test", "evidence review"]','["Assessed system, version, environment and scope", "Relevant code, configuration, policy or architecture evidence", "Executed test input and observed result", "Identity, timestamp and evidence digest where appropriate"]','The control is observed in the assessed version, the negative test is denied or safely contained, and the evidence is attributable and reproducible.','The control is absent, self-declared only, bypassable, fail-open, cross-tenant, replayable, unauditable or outside the assessed scope.','A passing bounded check does not prove the absence of other paths, future regressions or risks outside the stated scope.','281566fe98733f90d60fc86a56a690314d7af89dd68a2b176313d3d5d9eb04bb','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,objective=excluded.objective,method=excluded.method,check_types_json=excluded.check_types_json,required_evidence_json=excluded.required_evidence_json,pass_condition=excluded.pass_condition,fail_condition=excluded.fail_condition,limitations=excluded.limitations,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
INSERT INTO risk_knowledge_solutions (id,entry_id,control_objective,recommended_remediation,default_owner,priority,implementation_principles_json,monitoring,containment,retest_acceptance_json,content_digest,created_at,updated_at) VALUES ('ARL-SOL-003','ARL-KB-003','Reduce the likelihood and impact of prohibited uses and harm boundaries are missing and make the remaining risk visible.','Define prohibited-use rules, refusal behaviour, escalation routes and enforcement tests; block prohibited actions at the policy and tool layers.','Risk and compliance owner','P0','["Apply enforcement outside the model where authority, identity, money, data or side effects are involved.", "Use least privilege and fail closed for material actions.", "Preserve versioned evidence and rollback."]','Monitor denials, bypass attempts, drift, exceptions, anomalous use and control failures with a named response owner.','Disable or scope the affected capability, revoke related authority and preserve evidence until remediation is verified.','["Repeat the original failure case against the exact remediated version.", "Run authorization, tenant, replay, race and malformed-input variants where applicable.", "Confirm expected denial or bounded safe behaviour and no unintended side effects.", "Record evidence digest, limitations, reviewer and retest status."]','9d011531a88c4a47bdfdc8f0899aa728a54fd31126247c1b045ee33d2c5920ad','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,control_objective=excluded.control_objective,recommended_remediation=excluded.recommended_remediation,default_owner=excluded.default_owner,priority=excluded.priority,implementation_principles_json=excluded.implementation_principles_json,monitoring=excluded.monitoring,containment=excluded.containment,retest_acceptance_json=excluded.retest_acceptance_json,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
