INSERT INTO risk_knowledge_checks (id,entry_id,objective,method,check_types_json,required_evidence_json,pass_condition,fail_condition,limitations,content_digest,created_at,updated_at) VALUES ('ARL-CHK-041','ARL-KB-041','Determine whether the assessed system prevents or detects: sensitive data is sent to the model unnecessarily.','Trace representative requests from source to provider and compare every field with the minimum data required for the stated purpose.','["declared-control review", "observed-control inspection", "negative or abuse test", "evidence review"]','["Assessed system, version, environment and scope", "Relevant code, configuration, policy or architecture evidence", "Executed test input and observed result", "Identity, timestamp and evidence digest where appropriate"]','The control is observed in the assessed version, the negative test is denied or safely contained, and the evidence is attributable and reproducible.','The control is absent, self-declared only, bypassable, fail-open, cross-tenant, replayable, unauditable or outside the assessed scope.','A passing bounded check does not prove the absence of other paths, future regressions or risks outside the stated scope.','64560610c117e6072f566df3869db31ceffc98c735ef910f44cfd7086fc3fcbc','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,objective=excluded.objective,method=excluded.method,check_types_json=excluded.check_types_json,required_evidence_json=excluded.required_evidence_json,pass_condition=excluded.pass_condition,fail_condition=excluded.fail_condition,limitations=excluded.limitations,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
INSERT INTO risk_knowledge_solutions (id,entry_id,control_objective,recommended_remediation,default_owner,priority,implementation_principles_json,monitoring,containment,retest_acceptance_json,content_digest,created_at,updated_at) VALUES ('ARL-SOL-041','ARL-KB-041','Reduce the likelihood and impact of sensitive data is sent to the model unnecessarily and make the remaining risk visible.','Minimise and pseudonymise inputs, redact secrets, use field allowlists and choose provider settings that meet retention and training constraints.','Data protection owner','P0','["Apply enforcement outside the model where authority, identity, money, data or side effects are involved.", "Use least privilege and fail closed for material actions.", "Preserve versioned evidence and rollback."]','Monitor denials, bypass attempts, drift, exceptions, anomalous use and control failures with a named response owner.','Disable or scope the affected capability, revoke related authority and preserve evidence until remediation is verified.','["Repeat the original failure case against the exact remediated version.", "Run authorization, tenant, replay, race and malformed-input variants where applicable.", "Confirm expected denial or bounded safe behaviour and no unintended side effects.", "Record evidence digest, limitations, reviewer and retest status."]','edccdf766206ddfd69e023c24a14298383c41ae3cfd17a398c6b9d35cceec009','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,control_objective=excluded.control_objective,recommended_remediation=excluded.recommended_remediation,default_owner=excluded.default_owner,priority=excluded.priority,implementation_principles_json=excluded.implementation_principles_json,monitoring=excluded.monitoring,containment=excluded.containment,retest_acceptance_json=excluded.retest_acceptance_json,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
