INSERT INTO risk_knowledge_checks (id,entry_id,objective,method,check_types_json,required_evidence_json,pass_condition,fail_condition,limitations,content_digest,created_at,updated_at) VALUES ('ARL-CHK-045','ARL-KB-045','Determine whether the assessed system prevents or detects: vector and embedding services expose raw or inferable data.','Test direct vector API access, namespace isolation, metadata filters, enumeration, export and inference across identities.','["declared-control review", "observed-control inspection", "negative or abuse test", "evidence review"]','["Assessed system, version, environment and scope", "Relevant code, configuration, policy or architecture evidence", "Executed test input and observed result", "Identity, timestamp and evidence digest where appropriate"]','The control is observed in the assessed version, the negative test is denied or safely contained, and the evidence is attributable and reproducible.','The control is absent, self-declared only, bypassable, fail-open, cross-tenant, replayable, unauditable or outside the assessed scope.','A passing bounded check does not prove the absence of other paths, future regressions or risks outside the stated scope.','394ac4e9192851df8fe20e2fabf8a0bc9e414bccd46678ea24d147ba2ae14991','2026-08-05','2026-08-05') ON CONFLICT(id) DO UPDATE SET entry_id=excluded.entry_id,objective=excluded.objective,method=excluded.method,check_types_json=excluded.check_types_json,required_evidence_json=excluded.required_evidence_json,pass_condition=excluded.pass_condition,fail_condition=excluded.fail_condition,limitations=excluded.limitations,content_digest=excluded.content_digest,updated_at=excluded.updated_at;
